import SpotifyWebApi from 'spotify-web-api-js';

const spotifyApi = new SpotifyWebApi();
const API_URL = 'http://localhost:3001/api';

// Function to set the access token
export const setAccessToken = (token) => {
  spotifyApi.setAccessToken(token);
};

// Function to validate the token
export const validateToken = async () => {
  try {
    await spotifyApi.getMe();
    return true;
  } catch (error) {
    console.error('Token validation failed:', error);
    return false;
  }
};

// Function to search tracks by a query
export const searchTracks = async (query) => {
  try {
    const response = await spotifyApi.searchTracks(query, { limit: 8 });
    return response.tracks.items;
  } catch (error) {
    console.error('Error fetching tracks:', error);
    return [];
  }
};

// Function to get the user's top artists
export const getTopArtists = async () => {
  try {
    const response = await spotifyApi.getMyTopArtists({ limit: 10 });
    return response.items;
  } catch (error) {
    if (error.status === 401) {
      alert('Your session expired or lacks necessary permissions. Please re-login.');
    }
    console.error('Error fetching top artists:', error);
    return [];
  }
};

// Function to get new releases for given artist IDs
export const getNewReleases = async (artistIds) => {
  try {
    const newReleases = await Promise.all(
      artistIds.map(async (id) => {
        const response = await spotifyApi.getArtistAlbums(id, {
          include_groups: 'album,single',
          limit: 5, // Fetch 5 latest releases per artist
        });
        return response.items;
      })
    );

    return newReleases.flat();
  } catch (error) {
    console.error('Error fetching new releases:', error);
    return [];
  }
};

// Function to exchange code for token (this is for OAuth handling)
export const exchangeToken = async (code) => {
  try {
    const response = await axios.post(`${API_URL}/exchange-token`, { code });
    const { accessToken, refreshToken } = response.data;

    // Store the tokens locally (or send to backend for storage)
    localStorage.setItem('spotifyAccessToken', accessToken);
    localStorage.setItem('spotifyRefreshToken', refreshToken);

    setAccessToken(accessToken); // Set access token in Spotify API wrapper
  } catch (error) {
    console.error('Error exchanging code for token:', error);
    throw error;
  }
};
